('node-0-35', 'phase-00-lesson-35-virtual-environments-modern-package-manag', 'module-1', 35, 'Lesson 1.35: Virtual Environments & Modern Package Management (uv / pip)', 'Prerequisites: Lesson 0.34', 'Prerequisites: Lesson 0.34 | Subtopics: 4 items', 'Systems project application', 100, 1, 120.0, 1750.0, '# Lesson 0.35: Virtual Environments & Modern Package Management (uv / pip)

